  fr["Sensors, ranges, response times and certifications for hazardous areas."] = "Capteurs, plages de mesure, temps de réponse et certifications pour zones dangereuses.";
  zh["Explosion-protected equipment"] = "防爆设备";
  fr["Explosion-protected equipment"] = "Équipements antidéflagrants";
  zh["ATEX or IECEx certification, zones and protection methods."] = "ATEX 或 IECEx 认证、区域分类和防护方式。";
